function SearchBar({ query, onChange, onSubmit }) {
  const handleKeyDown = (e) => {
    if (e.key === "Enter") {
      e.preventDefault();
      onSubmit();
    }
  };

  return (
    <div className="mx-auto flex w-full max-w-[620px] items-center gap-3 rounded-[24px] border-2 border-[#BFDCF7] bg-white px-5 py-4 shadow-[0_12px_40px_rgba(11,54,88,0.10)] transition-all focus-within:border-[#0D6EFD] focus-within:shadow-[0_8px_24px_rgba(13,110,253,0.18)]">
      <button
        type="button"
        onClick={onSubmit}
        aria-label="Buscar curso"
        className="flex shrink-0 items-center justify-center text-[#0D6EFD] transition-colors hover:text-[#0066CC]"
      >
        <Search size={20} />
      </button>
      <input
        value={query}
        onChange={(e) => onChange(e.target.value)}
        onKeyDown={handleKeyDown}
        type="text"
        placeholder="O que você quer aprender?"
        className="w-full bg-transparent font-figtree text-[16px] font-400 text-[#0B3658] placeholder:text-[#688dac] focus:outline-none"
      />
    </div>
  );
}

