/* ------------------------------------------------------------------ */
/*  CNPJ — deteccao e validacao (algoritmo oficial dos digitos verif.) */
/* ------------------------------------------------------------------ */

const CNPJ_REGEX = /\b\d{2}\.?\d{3}\.?\d{3}\/?\d{4}-?\d{2}\b/;

function extractCNPJCandidate(text) {
  const match = String(text).match(CNPJ_REGEX);
  return match ? match[0] : null;
}

function isValidCNPJ(raw) {
  const cnpj = String(raw).replace(/[^\d]/g, "");
  if (cnpj.length !== 14) return false;
  if (/^(\d)\1{13}$/.test(cnpj)) return false; // todos os digitos iguais

  const calcCheckDigit = (base) => {
    let sum = 0;
    let pos = base.length - 7;
    for (let i = base.length; i >= 1; i--) {
      sum += Number(base.charAt(base.length - i)) * pos--;
      if (pos < 2) pos = 9;
    }
    const result = sum % 11;
    return result < 2 ? 0 : 11 - result;
  };

  const digits = cnpj.substring(12);
  const firstCheck = calcCheckDigit(cnpj.substring(0, 12));
  if (firstCheck !== Number(digits.charAt(0))) return false;

  const secondCheck = calcCheckDigit(cnpj.substring(0, 13));
  if (secondCheck !== Number(digits.charAt(1))) return false;

  return true;
}

function linkify(text) {
  // primeiro separa URLs, depois trata **negrito** dentro de cada trecho de texto
  const urlParts = String(text).split(/(https?:\/\/[^\s)]+)/g);

  return urlParts.map((part, i) => {
    if (/^https?:\/\//.test(part)) {
      return (
        <a
          key={i}
          href={part}
          target="_blank"
          rel="noopener noreferrer"
          className="break-all font-600 underline decoration-[#0D6EFD]/40 underline-offset-2"
        >
          {part}
        </a>
      );
    }

    const boldParts = part.split(/(\*\*[^*]+\*\*)/g);
    return (
      <React.Fragment key={i}>
        {boldParts.map((seg, j) =>
          /^\*\*[^*]+\*\*$/.test(seg) ? (
            <strong key={j} className="font-700">
              {seg.slice(2, -2)}
            </strong>
          ) : (
            <React.Fragment key={j}>{seg}</React.Fragment>
          )
        )}
      </React.Fragment>
    );
  });
}

function ChatWidget() {
  const [open, setOpen] = useState(false);
  const [messages, setMessages] = useState([
    {
      id: "welcome",
      role: "assistant",
      content:
        "Olá! 👋 Sou o assistente virtual da Sala do Empreendedor de Triunfo-PE. Posso te ajudar a encontrar o curso certo da Loja Sebrae ou tirar dúvidas sobre vendas, finanças, planejamento e empreendedorismo. Me conta: o que você precisa melhorar no seu negócio?",
    },
  ]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");
  const scrollRef = useRef(null);
  const cnpjRegistradoRef = useRef(false);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, open, loading]);

  const coursesContext = useMemo(
    () =>
      COURSES.map(
        (c) => `- ${c.title} [${CATEGORY_LABEL[c.category]}] — ${c.url}`
      ).join("\n"),
    []
  );

  const systemPrompt = useMemo(
    () => `Você é o assistente virtual da Sala do Empreendedor de Triunfo-PE, um serviço de apoio a empreendedores que dá acesso gratuito a capacitações da Loja Sebrae.

Seu papel:
- Ajudar o visitante a encontrar o curso certo para a necessidade do negócio dele.
- Tirar dúvidas gerais sobre vendas, marketing, finanças, planejamento e empreendedorismo, sempre de forma prática e acessível.

Regras importantes:
- Responda sempre em português do Brasil, em tom caloroso, direto e profissional.
- Você só pode recomendar cursos que estejam na lista abaixo. Nunca invente cursos, links, duração, preço, certificado ou nível que não estejam explicitamente na lista.
- Ao recomendar, cite o nome exato do curso e o link completo.
- Recomende no máximo 3 cursos por resposta, priorizando os mais relevantes para o que a pessoa descreveu.
- Se nenhum curso da lista atender exatamente à necessidade, seja honesto e sugira o mais próximo disponível.
- Mantenha as respostas curtas (idealmente até 120 palavras), como uma conversa de chat.
- Depois de ajudar a pessoa (recomendar cursos ou tirar uma dúvida), você pode, no máximo uma vez por conversa, perguntar de forma natural e não insistente se ela gostaria de registrar esse atendimento, pedindo o CNPJ da empresa. Nunca peça outros dados pessoais. Se a pessoa não quiser ou ignorar, não insista de novo.

Lista completa dos 37 cursos disponíveis (título, categoria e link):
${coursesContext}`,
    [coursesContext]
  );

  const handleSend = async () => {
    const text = input.trim();
    if (!text || loading) return;

    const newMessages = [
      ...messages,
      { id: `u-${Date.now()}`, role: "user", content: text },
    ];
    setMessages(newMessages);
    setInput("");
    setLoading(true);
    setErrorMsg("");

    try {
      const response = await fetch("/api/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          system: systemPrompt,
          messages: newMessages.map((m) => ({
            role: m.role,
            content: m.content,
          })),
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data?.error || "Falha na resposta da API");
      }

      const replyText = (data.content || [])
        .map((block) => (block.type === "text" ? block.text : ""))
        .filter(Boolean)
        .join("\n");

      setMessages((prev) => [
        ...prev,
        {
          id: `a-${Date.now()}`,
          role: "assistant",
          content:
            replyText ||
            "Desculpe, não consegui gerar uma resposta agora. Pode tentar reformular a pergunta?",
        },
      ]);

      // Verifica se a pessoa informou um CNPJ nessa mensagem e ainda
      // não registramos nenhum atendimento nesta conversa
      if (!cnpjRegistradoRef.current) {
        const candidate = extractCNPJCandidate(text);
        if (candidate && isValidCNPJ(candidate)) {
          cnpjRegistradoRef.current = true;
          try {
            const sfRes = await fetch("/api/collect-cnpj", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({ cnpj: candidate }),
            });
            const sfData = await sfRes.json();
            setMessages((prev) => [
              ...prev,
              {
                id: `sys-${Date.now()}`,
                role: "assistant",
                content: sfRes.ok
                  ? "✅ Prontinho — registrei esse atendimento por aqui, com o CNPJ informado."
                  : `Não consegui registrar o atendimento agora (${
                      sfData?.error || "erro desconhecido"
                    }). Pode tentar de novo mais tarde.`,
              },
            ]);
          } catch (e) {
            cnpjRegistradoRef.current = false;
            setMessages((prev) => [
              ...prev,
              {
                id: `sys-${Date.now()}`,
                role: "assistant",
                content:
                  "Não consegui registrar o atendimento agora. Pode tentar de novo mais tarde.",
              },
            ]);
          }
        }
      }
    } catch (err) {
      setErrorMsg(
        err?.message ||
          "Não consegui me conectar agora. Verifique sua internet e tente novamente."
      );
    } finally {
      setLoading(false);
    }
  };

  const handleKeyDown = (e) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <>
      <div className="fixed bottom-6 right-6 z-[60] flex items-center gap-3">
        {!open && (
          <span className="hidden rounded-[14px] bg-white px-3.5 py-2.5 font-figtree text-[13px] font-700 text-[#0B3658] shadow-[0_8px_24px_rgba(11,54,88,0.15)] sm:inline-block">
            Precisa de ajuda? 💬
          </span>
        )}

        <button
          onClick={() => setOpen((v) => !v)}
          aria-label={open ? "Fechar chat" : "Abrir chat com o assistente"}
          className="group relative flex h-16 w-16 items-center justify-center rounded-full text-white transition-transform duration-200 hover:-translate-y-1 hover:scale-105"
        >
          {!open && (
            <span
              aria-hidden="true"
              className="chat-pulse-ring absolute inset-0 rounded-full bg-[#0D6EFD]"
            />
          )}
          <span
            aria-hidden="true"
            className="absolute inset-0 rounded-full bg-gradient-to-br from-[#1CB0F6] to-[#0066CC] shadow-[0_14px_36px_rgba(0,102,204,0.45)] transition-shadow duration-200 group-hover:shadow-[0_18px_44px_rgba(0,102,204,0.55)]"
          />
          <span className="relative z-10 flex h-full w-full items-center justify-center">
            {open ? (
              <X size={26} strokeWidth={3} className="text-black" />
            ) : (
              <img
                src={CHAT_AVATAR}
                alt="Assistente da Sala do Empreendedor"
                className="chat-ia-avatar"
              />
            )}
          </span>
          {!open && (
            <span
              aria-hidden="true"
              className="absolute -right-0.5 -top-0.5 z-10 h-4 w-4 rounded-full border-2 border-white bg-[#1CB0F6]"
            />
          )}
        </button>
      </div>

      {open && (
        <div className="fixed bottom-24 right-4 z-[60] flex h-[min(560px,70vh)] w-[360px] max-w-[calc(100vw-2rem)] flex-col overflow-hidden rounded-[20px] border border-[#DCEBFA] bg-white shadow-[0_20px_60px_rgba(11,54,88,0.28)] sm:right-6">
          <div className="flex items-center gap-3 bg-gradient-to-r from-[#0066CC] to-[#0B3658] px-4 py-4">
            <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-white/15">
              <Bot size={18} className="text-white" />
            </span>
            <div className="min-w-0">
              <p className="font-figtree text-[14px] font-700 text-white">
                Assistente da Sala
              </p>
              <p className="truncate font-figtree text-[11px] font-400 text-[#BFDCF7]">
                Tire dúvidas e encontre o curso ideal
              </p>
            </div>
          </div>

          <div
            ref={scrollRef}
            className="min-h-0 flex-1 space-y-3 overflow-y-auto px-4 py-4"
          >
            {messages.map((m) => {
              const isUser = m.role === "user";
              return (
                <div
                  key={m.id}
                  className={`flex ${isUser ? "justify-end" : "justify-start"}`}
                >
                  <div
                    className="max-w-[85%] whitespace-pre-wrap rounded-[14px] px-3.5 py-2.5 font-figtree text-[13px] leading-[1.5]"
                    style={{
                      backgroundColor: isUser ? "#0066CC" : "#F3F8FC",
                      color: isUser ? "#FFFFFF" : "#0B3658",
                    }}
                  >
                    {linkify(m.content)}
                  </div>
                </div>
              );
            })}

            {loading && (
              <div className="flex justify-start">
                <div className="flex items-center gap-1.5 rounded-[14px] bg-[#F3F8FC] px-4 py-3">
                  <span
                    className="h-1.5 w-1.5 animate-bounce rounded-full bg-[#0066CC]"
                    style={{ animationDelay: "0ms" }}
                  />
                  <span
                    className="h-1.5 w-1.5 animate-bounce rounded-full bg-[#0066CC]"
                    style={{ animationDelay: "150ms" }}
                  />
                  <span
                    className="h-1.5 w-1.5 animate-bounce rounded-full bg-[#0066CC]"
                    style={{ animationDelay: "300ms" }}
                  />
                </div>
              </div>
            )}

            {errorMsg && (
              <p className="text-center font-figtree text-[12px] font-600 text-[#C0392B]">
                {errorMsg}
              </p>
            )}
          </div>

          <div className="flex items-center gap-2 border-t border-[#E6F1FA] px-3 py-3">
            <input
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder="Digite sua dúvida..."
              className="flex-1 rounded-[14px] border border-[#DCEBFA] bg-[#F3F8FC] px-3 py-2 font-figtree text-[13px] text-[#0B3658] placeholder:text-[#688dac] focus:outline-none focus:border-[#0D6EFD]"
            />
            <button
              type="button"
              onClick={handleSend}
              disabled={loading || !input.trim()}
              aria-label="Enviar mensagem"
              className="flex h-9 w-9 shrink-0 items-center justify-center rounded-[12px] bg-[#0066CC] text-white transition-colors duration-200 hover:bg-[#0D6EFD] disabled:cursor-not-allowed disabled:opacity-40"
            >
              <Send size={16} />
            </button>
          </div>
        </div>
      )}
    </>
  );
}

export default function SalaDoEmpreendedor() {
  const [activeCategory, setActiveCategory] = useState("todos");
  const [searchQuery, setSearchQuery] = useState("");

  const scrollTo = (id) => {
    const el = document.getElementById(id === "topo" ? "topo" : id);
    if (el) el.scrollIntoView({ behavior: "smooth", block: "start" });
  };

  const handleHeroSubmit = () => {
    setActiveCategory("todos");
    scrollTo("cursos");
  };

  const handleCategorySelect = (id) => {
    setActiveCategory((current) => (current === id ? "todos" : id));
    scrollTo("cursos");
  };

  const handleExplore = () => {
    setActiveCategory("todos");
    scrollTo("cursos");
  };

  return (
    <div className="min-h-screen w-full bg-white font-figtree">
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Nunito+Sans:wght@400;500;600;700;800&display=swap');
        .font-figtree { font-family: 'Nunito Sans', 'Plus Jakarta Sans', ui-sans-serif, system-ui, sans-serif; }
        .font-400 { font-weight: 400; }
        .font-600 { font-weight: 600; }
        .font-700 { font-weight: 700; }
        .font-800 { font-weight: 800; }
        @keyframes lightRaysSpin {
          from { transform: translate(-50%, -50%) rotate(0deg); }
          to { transform: translate(-50%, -50%) rotate(360deg); }
        }
        .light-rays {
          transform: translate(-50%, -50%);
          animation: lightRaysSpin 70s linear infinite;
        }
        @keyframes chatPulse {
          0% { transform: scale(1); opacity: 0.55; }
          70% { transform: scale(1.9); opacity: 0; }
          100% { transform: scale(1.9); opacity: 0; }
        }
        .chat-pulse-ring {
          animation: chatPulse 2.2s ease-out infinite;
        }
        .chat-ia-avatar {
          width: 40px;
          height: 40px;
          object-fit: contain;
          display: block;
        }
        @media (prefers-reduced-motion: reduce) {
          .light-rays { animation: none; }
          .chat-pulse-ring { animation: none; }
        }
      `}</style>

      <Header activeCategory={activeCategory} onExplore={handleExplore} onNav={scrollTo} />

      <Hero
        query={searchQuery}
        onQueryChange={setSearchQuery}
        onSubmit={handleHeroSubmit}
        total={COURSES.length}
      />

      <Categories activeCategory={activeCategory} onSelect={handleCategorySelect} />

      <Courses
        activeCategory={activeCategory}
        onSelectCategory={setActiveCategory}
        query={searchQuery}
        onQueryChange={setSearchQuery}
      />

      <LearningPaths onSelectCategory={handleCategorySelect} />

      <StatBanner onExplore={handleExplore} />

      <DarkCTA />

      <Footer onSelectCategory={handleCategorySelect} onNav={scrollTo} />

      <ChatWidget />
    </div>
  );
}
